mapper.select:
SELECT d.id, d.device_code AS deviceCode, d.device_name AS deviceName, d.device_type_id AS deviceTypeId, dt.type_name AS deviceTypeName, dt.type_category AS deviceTypeCategory, d.gateway_id AS gatewayId, g.gateway_name AS gatewayName, d.plot_id AS plotId, p.plot_name AS plotName, d.location_lat AS locationLat, d.location_lng AS locationLng, d.location_name AS locationName, d.online_status AS onlineStatus, CASE d.online_status WHEN 1 THEN '在线' ELSE '离线' END AS onlineStatusText, d.last_online_time AS lastOnlineTime, d.last_report_time AS lastReportTime, d.device_status AS deviceStatus, CASE d.device_status WHEN 'normal' THEN '正常' WHEN 'running' THEN '运行中' WHEN 'fault' THEN '故障' ELSE '未知' END AS deviceStatusText, d.protocol, d.firmware_version AS firmwareVersion, d.status, CASE d.status WHEN 1 THEN '正常' WHEN 2 THEN '停用' WHEN 3 THEN '报废' ELSE '未知' END AS statusText, d.create_by AS createBy, d.create_time AS createTime FROM agri_iot_device d LEFT JOIN agri_iot_device_type dt ON d.device_type_id = dt.id LEFT JOIN agri_iot_gateway g ON d.gateway_id = g.id LEFT JOIN agri_iot_plot p ON d.plot_id = p.id WHERE d.del_flag = 0
AND d.device_code LIKE CONCAT('%', #{dto.deviceCode}, '%')
AND d.device_name LIKE CONCAT('%', #{dto.deviceName}, '%')
AND d.device_type_id = #{dto.deviceTypeId}
AND d.plot_id = #{dto.plotId}
AND d.online_status = #{dto.onlineStatus}
AND d.status = #{dto.status}
ORDER BY d.create_time DESC LIMIT #{dto.pageNum}, #{dto.pageSize}

SELECT COUNT(*)
FROM agri_iot_device d
WHERE d.del_flag = 0

    AND d.device_code LIKE CONCAT('%', #{dto.deviceCode}, '%')


    AND d.device_name LIKE CONCAT('%', #{dto.deviceName}, '%')


    AND d.device_type_id = #{dto.deviceTypeId}


    AND d.plot_id = #{dto.plotId}


    AND d.online_status = #{dto.onlineStatus}


    AND d.status = #{dto.status}
